    source: "Al Jazeera",
    url: "https://www.aljazeera.com/news/2026/8/31/poland-opens-terror-probe-into-fire-at-drone-factory?traffic_source=rss",
    time: "2 ore fa",
    pub_ts: 1788211455,
    published_at: "2026-08-31T21:24:15+00:00",
    language: "en",
    score: 1,
